// Goldman Sachs ops extracts. Only the Goldman agent may import this module.
// Schemas follow data/DATA_DICTIONARY.md; /data is regenerated by script, never edited by hand.
import "server-only";
import { z } from "zod";
import { DTC_REF, GS_TRADE, ISIN, PARTICIPANT, date, gsTs, id, int, loadTables, nullable, num, text } from "./core";

const SIDE = z.enum(["BUY", "SELL"]);

export const tradeBlotterSchema = z.object({
  gs_trade_ref: id(GS_TRADE),
  exec_ts_utc: gsTs(),
  client_name: text(),
  side: SIDE,
  client_side: SIDE,
  ticker: nullable(text()),
  isin: id(ISIN),
  quantity: num(),
  price: num(),
  gross_amount: num(),
  commission: num(),
  trade_date: date(),
  settle_date: date(),
  desk: text(),
  trader_id: text(),
  status: z.enum(["BOOKED"]),
});

export const allocationConfirmSchema = z.object({
  alloc_id: id(/^AL-\d{8}-\d{6}-\d+$/),
  gs_trade_ref: id(GS_TRADE),
  client_name: text(),
  client_account_ref: text(),
  quantity: num(),
  custodian_name: text(),
  custodian_dtc_participant: id(PARTICIPANT),
  ctm_confirm_id: id(/^CTM-\d{8}$/),
  affirmed: z.enum(["Y", "N"]),
  affirmed_ts_utc: nullable(gsTs()),
  version: int(),
  status: z.enum(["AFFIRMED", "PENDING_AFFIRMATION", "SUPERSEDED"]),
});

export const deliverySchema = z.object({
  // A block trade allocated to several accounts has one delivery per allocation: DEL-…-1, -2.
  delivery_id: id(/^DEL-\d{8}-\d{6}(-\d+)?$/),
  gs_trade_ref: id(GS_TRADE),
  dtc_reference: id(DTC_REF),
  from_participant: id(PARTICIPANT),
  to_participant: id(PARTICIPANT),
  isin: id(ISIN),
  quantity: num(),
  settlement_amount: num(),
  instructed_ts_utc: gsTs(),
  status: z.enum(["DELIVERED", "SETTLED", "PENDING", "DK"]),
  status_ts_utc: gsTs(),
  dk_reason: nullable(text()),
});

export const failSchema = z.object({
  gs_fail_id: id(/^GS-FAIL-\d{8}-\d{4}$/),
  delivery_id: id(/^DEL-\d{8}-\d{6}(-\d+)?$/),
  counterparty_custodian: text(),
  // When Goldman delivers: SHORT_INVENTORY, DK_BY_RECEIVER, HELD, CPTY_CASH. When it receives:
  // CPTY_FAILED_TO_DELIVER, DK_ISSUED (Goldman DK'd the delivery). Either way: CPTY_SSI_MISMATCH, UNAFFIRMED.
  fail_reason: z.enum(["SHORT_INVENTORY", "CPTY_SSI_MISMATCH", "UNAFFIRMED", "DK_BY_RECEIVER", "HELD", "CPTY_CASH", "CPTY_FAILED_TO_DELIVER", "DK_ISSUED"]),
  opened_ts_utc: gsTs(),
  age_days: int(),
  exposure_usd: num(),
  owner: nullable(text()),
  next_action: text(),
  status: z.enum(["OPEN", "CLOSED"]),
});

export const inventorySchema = z.object({
  as_of_date: date(),
  isin: id(ISIN),
  box_location: text(),
  quantity_available: num(),
  quantity_pledged: num(),
  quantity_on_loan: num(),
});

export const ssiBookSchema = z.object({
  ssi_ref: id(/^GSSSI-\d{5}$/),
  custodian_name: text(),
  client_name: text(),
  market: text(),
  dtc_participant: id(PARTICIPANT),
  effective_date: date(),
  status: z.enum(["ACTIVE"]),
});

export const stockLoanSchema = z.object({
  loan_id: id(/^SL-\d+$/),
  isin: id(ISIN),
  quantity: num(),
  counterparty: text(),
  direction: z.enum(["LEND", "BORROW"]),
  start_date: date(),
  recall_status: z.enum(["NONE", "RECALLED", "RECALL_PENDING"]),
});

const schemas = {
  trade_blotter: tradeBlotterSchema,
  allocations_confirms: allocationConfirmSchema,
  deliveries: deliverySchema,
  fails: failSchema,
  inventory: inventorySchema,
  ssi_book: ssiBookSchema,
  stock_loan: stockLoanSchema,
};

export type GsTrade = z.output<typeof tradeBlotterSchema>;
export type GsAllocationConfirm = z.output<typeof allocationConfirmSchema>;
export type GsDelivery = z.output<typeof deliverySchema>;
export type GsFail = z.output<typeof failSchema>;
export type GsInventory = z.output<typeof inventorySchema>;
export type GsSsi = z.output<typeof ssiBookSchema>;
export type GsStockLoan = z.output<typeof stockLoanSchema>;
export type GoldmanData = ReturnType<typeof loadGoldman>;

let cache: ReturnType<typeof load> | undefined;
const load = () => loadTables("goldman", schemas);

/** All Goldman Sachs tables, parsed once and cached in memory. */
export function loadGoldman() {
  return (cache ??= load());
}
